<script setup>
import{onMounted,ref}from'vue';import{api}from'../api.js';import AdminNav from'../components/AdminNav.vue';import SkeletonRows from'../components/SkeletonRows.vue';import{apiErrorMessage}from'../stores/notifications.js'
const items=ref([]),loading=ref(true),error=ref(''),busy=ref(null)
async function load(){loading.value=true;error.value='';try{items.value=(await api.get('/api/admin/player-link-requests')).data}catch(e){error.value=apiErrorMessage(e,'Не удалось загрузить заявки.')}finally{loading.value=false}}
async function review(item,decision){if(busy.value)return;busy.value=item.id;error.value='';try{await api.post(`/api/admin/player-link-requests/${item.id}/${decision}`);items.value=items.value.filter(row=>row.id!==item.id)}catch(e){error.value=apiErrorMessage(e,'Не удалось обработать заявку.')}finally{busy.value=null}}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">АДМИНКА</p><h1>Заявки</h1><p class="muted">Привязка Discord-пользователей к персонажам</p></div><button :disabled="loading" @click="load">Обновить</button></div><AdminNav/><p v-if="error" class="notice error">{{ error }} <button @click="load">Повторить</button></p><div class="panel"><SkeletonRows v-if="loading" :rows="4"/><div v-else-if="items.length" class="link-request-list"><article v-for="item in items" :key="item.id"><div><strong>{{ item.user?.discord_display_name||item.user?.discord_username }}</strong><small>@{{ item.user?.discord_username }}</small></div><span>хочет привязать</span><div><strong>{{ item.player?.nickname }}</strong><small>{{ item.player?.class }}</small></div><div class="link-request-actions"><button class="primary" :disabled="busy" @click="review(item,'approve')">Подтвердить</button><button class="danger" :disabled="busy" @click="review(item,'reject')">Отклонить</button></div></article></div><div v-else class="empty-state"><strong>Новых заявок нет</strong><p>Все запросы на привязку обработаны.</p></div></div></section></template>
